package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class StringUtils_newStringIso8859_1_TriageGen2Test {

    @Test
    public void testNewStringIso8859_1_StandardAscii() {
        byte[] bytes = {65, 66, 67, 68}; // "ABCD"
        String expected = "ABCD";
        String actual = StringUtils.newStringIso8859_1(bytes);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_Iso8859_1SpecificChars() {
        // 0xA9 is Copyright symbol © in ISO-8859-1
        // 0xFF is y with diaeresis ý in ISO-8859-1
        byte[] bytes = {(byte) 0xA9, (byte) 0xFF};
        String expected = "\u00A9\u00FF";
        String actual = StringUtils.newStringIso8859_1(bytes);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_EmptyArray() {
        byte[] bytes = new byte[0];
        String expected = "";
        String actual = StringUtils.newStringIso8859_1(bytes);
        assertEquals(expected, actual);
    }

    @Test
    public void testNewStringIso8859_1_NullInput() {
        // The behavior of new String(null, Charset) in Java is to throw a NullPointerException.
        // Since this is a direct wrapper, we test that it propagates the NPE.
        try {
            StringUtils.newStringIso8859_1(null);
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testNewStringIso8859_1_MixedValues() {
        byte[] bytes = {0, 1, 127, (byte) 128, (byte) 255};
        // ISO-8859-1 maps bytes 0-255 directly to Unicode U+0000-U+00FF
        String expected = "\u0000\u0001\u007F\u0080\u00FF";
        String actual = StringUtils.newStringIso8859_1(bytes);
        assertEquals(expected, actual);
    }
}
